r"""
Crescopus - withdraw a card instead of deleting it

Builders can withdraw an app card and growers can withdraw their own card.
A withdrawn card is hidden from browsing, its pending requests are declined,
and the person chooses which active partnerships to end. Plans and ledgers
stay with both people, and the card can be restored from the dashboard.
An app card with no history can still be deleted outright.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_card_withdraw.py
  3. Run sql/migration_card_withdraw.sql in the Supabase SQL editor. Safe to re-run.
  4. Any file it replaces is copied first to _backup_apply_card_withdraw\.

Your .env is never read or changed.
"""
import base64, os, shutil, sys

FILES = [
    ("sql/migration_card_withdraw.sql", ""),
    ("app/browse/routes.py", ""),
    ("app/listings/routes.py", ""),
    ("app/connection_requests/routes.py", ""),
    ("app/builders/routes.py", ""),
    ("app/dashboard/routes.py", ""),
    ("app/templates/browse/withdraw.html", ""),
    ("app/templates/browse/_app_popup.html", ""),
    ("app/templates/browse/_grower_popup.html", ""),
    ("app/templates/browse/edit_card.html", ""),
    ("app/templates/dashboard/index.html", ""),
    ("app/static/css/cresco-ui.css", "")
]
BACKUP = "_backup_apply_card_withdraw"
NEXT = "paste sql/migration_card_withdraw.sql into the Supabase SQL editor and run it, restart python wsgi.py, then commit and push."

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")
    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64 in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                if fh.read() == data:
                    print("same     " + rel)
                    continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
